INSERT INTO `api_aichat` (`id`, `question`, `answer`, `created_at`, `updated_at`) VALUES
(4, 'lung opacity chest x-ray', 'Observations:\nIncreased opacity in the lung field.\n\nPossible Findings:\nMay indicate infection, fluid accumulation, or inflammation.\n\nDifferential Diagnosis:\n- Pneumonia\n- Pulmonary edema\n- Atelectasis\n\nRecommendation:\nClinical correlation and further imaging may be required.\n\nDisclaimer:\nThis analysis is AI-assisted and should be reviewed by a qualified radiologist or physician.', '2026-03-17 07:38:52.233683', '2026-03-17 07:38:52.233732'),
(5, 'fracture x-ray', 'Observations:\nDiscontinuity or break in bone structure.\n\nPossible Findings:\nIndicates bone fracture or crack.\n\nDifferential Diagnosis:\n- Acute fracture\n- Stress fracture\n- Pathological fracture\n\nRecommendation:\nOrthopedic evaluation and possible immobilization advised.\n\nDisclaimer:\nThis analysis is AI-assisted and should be reviewed by a qualified radiologist or physician.', '2026-03-17 07:38:52.238153', '2026-03-17 07:38:52.238171'),
(6, 'brain hemorrhage ct', 'Observations:\nHyperdense region in brain tissue.\n\nPossible Findings:\nSuggestive of intracranial bleeding.\n\nDifferential Diagnosis:\n- Intracerebral hemorrhage\n- Subdural hematoma\n- Epidural hematoma\n\nRecommendation:\nImmediate clinical evaluation and emergency care required.\n\nDisclaimer:\nThis analysis is AI-assisted and should be reviewed by a qualified radiologist or physician.', '2026-03-17 07:38:52.242708', '2026-03-17 07:38:52.242737'),
(7, 'hypodense lesion ct', 'Observations:\nArea of lower density compared to surrounding tissue.\n\nPossible Findings:\nMay indicate fluid, cyst, or tissue damage.\n\nDifferential Diagnosis:\n- Cyst\n- Infarction\n- Necrosis\n\nRecommendation:\nFurther imaging with contrast may be useful.\n\nDisclaimer:\nThis analysis is AI-assisted and should be reviewed by a qualified radiologist or physician.', '2026-03-17 07:38:52.246842', '2026-03-17 07:38:52.246861'),
(8, 'hyperintensity mri', 'Observations:\nBright signal area on MRI scan.\n\nPossible Findings:\nIndicates abnormal tissue or fluid presence.\n\nDifferential Diagnosis:\n- Edema\n- Tumor\n- Inflammation\n\nRecommendation:\nCorrelation with clinical findings is advised.\n\nDisclaimer:\nThis analysis is AI-assisted and should be reviewed by a qualified radiologist or physician.', '2026-03-17 07:38:52.251197', '2026-03-17 07:38:52.251215'),
(9, 'ligament tear mri', 'Observations:\nDisruption or irregularity in ligament structure.\n\nPossible Findings:\nSuggests ligament injury or tear.\n\nDifferential Diagnosis:\n- Partial tear\n- Complete tear\n- Sprain\n\nRecommendation:\nOrthopedic consultation recommended.\n\nDisclaimer:\nThis analysis is AI-assisted and should be reviewed by a qualified radiologist or physician.', '2026-03-17 07:38:52.258417', '2026-03-17 07:38:52.258435'),
(10, 'pleural effusion x-ray', 'Observations:\nBlunting of costophrenic angle and fluid level.\n\nPossible Findings:\nFluid accumulation in pleural space.\n\nDifferential Diagnosis:\n- Pleural effusion\n- Infection\n- Heart failure\n\nRecommendation:\nFurther evaluation with ultrasound or CT advised.\n\nDisclaimer:\nThis analysis is AI-assisted and should be reviewed by a qualified radiologist or physician.', '2026-03-17 07:38:52.262143', '2026-03-17 07:38:52.262164'),
(11, 'kidney stones ct', 'Observations:\nHyperdense structures in kidney or ureter.\n\nPossible Findings:\nIndicates presence of calculi (stones).\n\nDifferential Diagnosis:\n- Renal calculi\n- Ureteric stones\n\nRecommendation:\nUrological consultation advised.\n\nDisclaimer:\nThis analysis is AI-assisted and should be reviewed by a qualified radiologist or physician.', '2026-03-17 07:38:52.265644', '2026-03-17 07:38:52.265663'),
(12, 'brain tumor mri', 'Observations:\nAbnormal mass with altered signal intensity.\n\nPossible Findings:\nSuggests presence of tumor.\n\nDifferential Diagnosis:\n- Primary tumor\n- Metastasis\n- Glioma\n\nRecommendation:\nFurther evaluation with contrast MRI and biopsy.\n\nDisclaimer:\nThis analysis is AI-assisted and should be reviewed by a qualified radiologist or physician.', '2026-03-17 07:38:52.269814', '2026-03-17 07:38:52.269833'),
(13, 'stroke ct findings', 'Observations:\nHypodense or hyperdense regions in brain.\n\nPossible Findings:\nIndicates ischemic or hemorrhagic stroke.\n\nDifferential Diagnosis:\n- Ischemic stroke\n- Hemorrhagic stroke\n\nRecommendation:\nImmediate medical attention required.\n\nDisclaimer:\nThis analysis is AI-assisted and should be reviewed by a qualified radiologist or physician.', '2026-03-17 07:38:52.273353', '2026-03-17 07:38:52.273372'),
(14, 'pneumothorax x-ray', 'Observations:\nAbsence of lung markings with visible pleural line.\n\nPossible Findings:\nIndicates air in pleural space causing lung collapse.\n\nDifferential Diagnosis:\n- Spontaneous pneumothorax\n- Traumatic pneumothorax\n\nRecommendation:\nImmediate clinical attention required.\n\nDisclaimer:\nThis analysis is AI-assisted and should be reviewed by a qualified radiologist or physician.', '2026-03-17 07:38:52.277142', '2026-03-17 07:38:52.277161'),
(15, 'osteoporosis x-ray', 'Observations:\nReduced bone density and thinning of cortical bone.\n\nPossible Findings:\nIndicates weakened bone structure.\n\nDifferential Diagnosis:\n- Osteoporosis\n- Osteopenia\n\nRecommendation:\nBone density test (DEXA scan) recommended.\n\nDisclaimer:\nThis analysis is AI-assisted and should be reviewed by a qualified radiologist or physician.', '2026-03-17 07:38:52.281421', '2026-03-17 07:38:52.281442'),
(16, 'pulmonary embolism ct', 'Observations:\nFilling defect in pulmonary arteries.\n\nPossible Findings:\nIndicates blockage due to clot.\n\nDifferential Diagnosis:\n- Pulmonary embolism\n- Vascular obstruction\n\nRecommendation:\nUrgent medical intervention required.\n\nDisclaimer:\nThis analysis is AI-assisted and should be reviewed by a qualified radiologist or physician.', '2026-03-17 07:38:52.285166', '2026-03-17 07:38:52.285186'),
(17, 'appendicitis ct scan', 'Observations:\nEnlarged appendix with wall thickening.\n\nPossible Findings:\nSuggests inflammation of appendix.\n\nDifferential Diagnosis:\n- Acute appendicitis\n- Abscess\n\nRecommendation:\nSurgical consultation recommended.\n\nDisclaimer:\nThis analysis is AI-assisted and should be reviewed by a qualified radiologist or physician.', '2026-03-17 07:38:52.288906', '2026-03-17 07:38:52.288928'),
(18, 'stroke mri findings', 'Observations:\nDiffusion restriction in affected brain area.\n\nPossible Findings:\nIndicates acute ischemic stroke.\n\nDifferential Diagnosis:\n- Ischemic stroke\n- Transient ischemic attack\n\nRecommendation:\nImmediate neurological evaluation required.\n\nDisclaimer:\nThis analysis is AI-assisted and should be reviewed by a qualified radiologist or physician.', '2026-03-17 07:38:52.292953', '2026-03-17 07:38:52.292973'),
(19, 'meniscus tear mri', 'Observations:\nAbnormal signal in meniscus structure.\n\nPossible Findings:\nSuggests tear or degeneration.\n\nDifferential Diagnosis:\n- Meniscus tear\n- Degenerative changes\n\nRecommendation:\nOrthopedic consultation advised.\n\nDisclaimer:\nThis analysis is AI-assisted and should be reviewed by a qualified radiologist or physician.', '2026-03-17 07:38:52.297193', '2026-03-17 07:38:52.297216'),
(20, 'scoliosis x-ray', 'Observations:\nLateral curvature of spine.\n\nPossible Findings:\nIndicates abnormal spinal alignment.\n\nDifferential Diagnosis:\n- Scoliosis\n- Postural deformity\n\nRecommendation:\nSpine specialist consultation recommended.\n\nDisclaimer:\nThis analysis is AI-assisted and should be reviewed by a qualified radiologist or physician.', '2026-03-17 07:38:52.302381', '2026-03-17 07:38:52.302416'),
(21, 'liver cirrhosis ct', 'Observations:\nIrregular liver contour with nodular surface.\n\nPossible Findings:\nSuggests chronic liver damage.\n\nDifferential Diagnosis:\n- Liver cirrhosis\n- Chronic hepatitis\n\nRecommendation:\nFurther clinical evaluation required.\n\nDisclaimer:\nThis analysis is AI-assisted and should be reviewed by a qualified radiologist or physician.', '2026-03-17 07:38:52.306215', '2026-03-17 07:38:52.306235'),
(22, 'spinal cord compression mri', 'Observations:\nCompression of spinal cord with signal changes.\n\nPossible Findings:\nIndicates nerve pressure or injury.\n\nDifferential Diagnosis:\n- Disc herniation\n- Tumor\n- Trauma\n\nRecommendation:\nUrgent neurological consultation required.\n\nDisclaimer:\nThis analysis is AI-assisted and should be reviewed by a qualified radiologist or physician.', '2026-03-17 07:38:52.311349', '2026-03-17 07:38:52.311377'),
(23, 'calcification ct imaging', 'Observations:\nHigh-density (bright) areas in tissues.\n\nPossible Findings:\nIndicates calcium deposits.\n\nDifferential Diagnosis:\n- Chronic infection\n- Tumor\n- Degenerative changes\n\nRecommendation:\nFurther evaluation based on clinical context.\n\nDisclaimer:\nThis analysis is AI-assisted and should be reviewed by a qualified radiologist or physician.', '2026-03-17 07:38:52.315028', '2026-03-17 07:38:52.315055');

